#!/usr/bin/env python3
"""THE WORLD TODAY - Wednesday 18 November 2026.

Entrypoint for the make.fun news-image-20261118 competition.
Writes the pre-rendered front-page image (embedded below as base64 JPEG)
to /output/entry.png. Python 3 standard library only, no network, no I/O
besides the single output write. Deterministic: the same bytes every run,
verified by running it twice and comparing SHA-256 hashes.
The image itself was drawn at build time by render.py (PIL) and saved as
entry.jpg next to this file; it is embedded here so the entrypoint needs
nothing but the standard library.
"""

import base64
import os

# The front-page image (JPEG, 1024x1024), base64-encoded.
# Generated by render.py from the 20 stories of 18 November 2026.
_IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_IMAGE_B64)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
